import pandas as pd
import numpy as np

# Load all available experiments
experiments = {}
for i in [1,2,3,4,5,6,8,9,10]:
    try:
        df = pd.read_csv(f'experiment_{i}_csv')
        experiments[i] = df
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(df.columns)}")
        # Show intervention levels if present
        int_cols = [c for c in df.columns if c not in ['CropYield', 'LeafGreennessIndex']]
        if int_cols:
            for c in int_cols:
                unique_vals = df[c].unique()
                if len(unique_vals) <= 3:
                    print(f"  {c}: {unique_vals}")
                else:
                    print(f"  {c}: mean={df[c].mean():.2f}, std={df[c].std():.2f}")
        # Show outcome stats
        if 'CropYield' in df.columns:
            print(f"  CropYield: mean={df['CropYield'].mean():.3f}, std={df['CropYield'].std():.3f}, n={len(df)}")
        if 'LeafGreennessIndex' in df.columns:
            print(f"  LeafGreennessIndex: mean={df['LeafGreennessIndex'].mean():.3f}, std={df['LeafGreennessIndex'].std():.3f}")
    except Exception as e:
        print(f"Error loading exp {i}: {e}")

# Combine all data
all_data = pd.concat(experiments.values(), ignore_index=True)
print(f"\n=== ALL DATA COMBINED ===")
print(f"Total rows: {len(all_data)}")
print(f"Columns: {list(all_data.columns)}")
print(all_data.describe())
